nFlow(\n  cancelAt: string | undefined,\n  launchWorkspaceId: string | null,\n  showFlow: LaunchCancellationFlowOptions['showFlow']\n): Promise<void> {\n  const workspaceStore = useTeamWorkspaceStore()\n  const isScopeCurrent = launchWorkspaceId\n    ? () => workspaceStore.activeWorkspaceId === launchWorkspaceId\n    : () => true\n\n  const flow = canOfferRetention(launchWorkspaceId)\n    ? await prepareRetentionFlow()\n    : null\n  if (!isScopeCurrent()) return\n\n  try {\n    await showFlow({\n      cancelAt,\n      surveyId: remoteConfig.value.cancellation_survey_id || undefined,\n      flow,\n      workspaceId: launchWorkspaceId,\n      isScopeCurrent\n    })\n  } catch (error) {\n    reportFlowNotShown(error, isScopeCurrent())\n  }\n}\n"],"mappings":"8UA6BA,SAAS,kBAAkB,EAAyB,CAClD,OACE,aAAiB,IAChB,EAAM,SAAW,KAAO,EAAM,SAAW,IAE9C,CAEA,eAAe,sBAA8D,CAC3E,GAAI,CACF,OAAO,MAAM,EAAa,qBAAqB,CACjD,OAAS,EAAO,CAQd,OAPK,kBAAkB,CAAK,GAC1B,EAAY,EAAO,CACjB,QAAS,UACT,UAAW,mCACX,MAAO,SACT,CAAC,EAEI,IACT,CACF,CAIA,eAAsB,yBACpB,EACA,EACoC,CACpC,GAAI,CAKF,OAJA,MAAM,EAAa,yBAAyB,CAC1C,WAAY,EACZ,OACF,CAAC,EACM,UACT,OAAS,EAAO,CAYd,OAVE,aAAiB,GACjB,EAAM,OAAS,0BAER,WAET,EAAY,EAAO,CACjB,QAAS,UACT,UAAW,yCACX,QAAS,CAAE,OAAM,CACnB,CAAC,EACM,SACT,CACF,CAEA,IAAM,EAAkB,IAAI,IAE5B,SAAgB,uBACd,EACe,CACf,IAAM,EACJ,EAAQ,oBAAsB,IAAA,GAC1B,EAAsB,CAAC,CAAC,kBACxB,EAAQ,kBACR,EAAU,EAAgB,IAAI,CAAiB,EACrD,GAAI,EAAS,OAAO,EAEpB,IAAM,EAAO,qBACX,EAAQ,SACR,EACA,EAAQ,QACV,CAAC,CAAC,YAAc,EAAgB,OAAO,CAAiB,CAAC,EAEzD,OADA,EAAgB,IAAI,EAAmB,CAAI,EACpC,CACT,CAEA,SAAS,kBAAkB,EAA2C,CACpE,IAAM,EAAiB,EAAsB,EAC7C,OACE,EAAkB,CAAC,CAAC,KAAK,QAAU,aACnC,CAAC,CAAC,GACF,EAAe,uBACf,EAA0B,EAAe,0BAA0B,CAEvE,CAEA,SAAS,mBAAmB,EAAgB,EAAgC,CAC1E,EAAY,EAAO,CACjB,QAAS,UACT,UAAW,kCACX,KAAM,CAAE,wBAAyB,CAAsB,EACvD,MAAO,EAAwB,QAAU,SAC3C,CAAC,EACI,GACL,EAAS,CAAC,CAAC,MAAM,EAAE,kCAAkC,EAAG,CACtD,SAAU,GACZ,CAAC,CACH,CAEA,eAAe,qBACb,EACA,EACA,EACe,CACf,IAAM,EAAiB,EAAsB,EACvC,EAAiB,MACb,EAAe,oBAAsB,MACrC,GAEJ,EAAO,kBAAkB,CAAiB,EAC5C,MAAM,qBAAq